{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "full",
      "summary_quote": "The bill would also add child trafficking prevention and awareness education to a list in Tennessee Code § 49-1-1002(a).",
      "rationale": "Identifies the amended provision and the required addition; the precise position within the list is not material."
    },
    {
      "proposition_id": "P2",
      "status": "full",
      "summary_quote": "It would delete subdivision (a)(13)(B) and the second sentence of subsection (d) in § 49-6-1304",
      "rationale": "Identifies the exact subdivision being deleted and its statutory section."
    },
    {
      "proposition_id": "P3",
      "status": "full",
      "summary_quote": "It would delete subdivision (a)(13)(B) and the second sentence of subsection (d) in § 49-6-1304",
      "rationale": "Identifies the exact sentence being deleted and its statutory section."
    },
    {
      "proposition_id": "P4",
      "status": "full",
      "summary_quote": "It defines child trafficking as a human trafficking offense under the cited statute involving a victim younger than 18.",
      "rationale": "Conveys the incorporated human trafficking offense definition and the victim age threshold."
    },
    {
      "proposition_id": "P5",
      "status": "full",
      "summary_quote": "The bill would require all Tennessee public schools, including public charter schools, to teach child trafficking prevention and awareness as part of health education in every grade from kindergarten through twelfth grade.",
      "rationale": "Conveys the mandatory instruction, public-school scope, health education placement, and all covered grades."
    },
    {
      "proposition_id": "P6",
      "status": "full",
      "summary_quote": "The instruction would have to follow state health education standards, suit students’ ages and grade levels, and build on earlier instruction each year.",
      "rationale": "Conveys standards-based instruction, age and grade appropriateness, and developmentally progressive learning each year within the previously stated school scope."
    },
    {
      "proposition_id": "P7",
      "status": "full",
      "summary_quote": "An LEA or public charter school could use a qualified healthcare professional or social worker to help teach it, but only if that person meets the cited requirements for assisting with family life instruction.",
      "rationale": "Conveys the authorized entities, eligible assisting professionals, and the family life teaching eligibility condition."
    },
    {
      "proposition_id": "P8",
      "status": "partial",
      "summary_quote": "By August 1, 2026, and every August 1 after that, each local board of education and public charter school governing body would have to send the education commissioner an implementation plan and post it on the LEA’s or school’s website. The plan would describe instruction for each grade served, the instructor’s qualifications, and the materials and resources used.",
      "rationale": "Covers the responsible bodies, annual deadline, recipient, publication, qualifications, and resources. Describing instruction for each grade does not expressly convey the required methods of delivering that instruction."
    },
    {
      "proposition_id": "P9",
      "status": "partial",
      "summary_quote": "The plan would describe instruction for each grade served, the instructor’s qualifications, and the materials and resources used. By July 1, 2027, and every July 1 after that, those bodies would have to report to the commissioner, verify that the instruction was provided during the preceding school year, and provide the same information.",
      "rationale": "Covers the responsible bodies, annual deadline, recipient, prior-year verification, and repeated plan information. The referenced description does not expressly include grade-level instruction delivery methods."
    },
    {
      "proposition_id": "P10",
      "status": "full",
      "summary_quote": "It would take effect upon becoming law and apply beginning with the 2026–2027 school year.",
      "rationale": "Conveys immediate effectiveness upon becoming law and application starting in 2026–2027 and continuing thereafter."
    }
  ]
}
